import io

def pad4(data):
    """Pad data to 4-byte boundary."""
    r = len(data) % 4
    if r:
        data += b'\x00' * (4 - r)
    return data

def calc_checksum(data):
    """Calculate OpenType table checksum."""
    data = pad4(data)
    total = 0
    for i in range(0, len(data), 4):
        total += struct.unpack('>I', data[i:i+4])[0]
    return total & 0xFFFFFFFF

def make_tag(s):
    return s.encode('ascii')

# CFF2 number encoding for charstrings
def encode_int_cs(val):
    """Encode an integer for CFF2 charstring."""
    if -107 <= val <= 107:
        return bytes([val + 139])
    elif 108 <= val <= 1131:
        val -= 108
        b0 = (val >> 8) + 247
        b1 = val & 0xFF
        return bytes([b0, b1])
    elif -1131 <= val <= -108:
        val = -val - 108
        b0 = (val >> 8) + 251
        b1 = val & 0xFF
        return bytes([b0, b1])
    else:
        # Use 3-byte encoding (28 xx xx) for int16
        return struct.pack('>Bh', 28, val)

# Build CFF2 INDEX structure
def make_index(data_list):
    """Build a CFF2 INDEX (count32 format)."""
    count = len(data_list)
    if count == 0:
        return struct.pack('>I', 0)  # count=0

    # Determine offSize
    total_data_size = sum(len(d) for d in data_list)
    last_offset = total_data_size + 1
    if last_offset <= 0xFF:
        offSize = 1
    elif last_offset <= 0xFFFF:
        offSize = 2
    elif last_offset <= 0xFFFFFF:
        offSize = 3
    else:
        offSize = 4

    result = struct.pack('>I', count)  # count (4 bytes in CFF2)
    result += struct.pack('B', offSize)

    # Write offsets (1-based)
    offset = 1
    for d in data_list:
        if offSize == 1:
            result += struct.pack('B', offset)
        elif offSize == 2:
            result += struct.pack('>H', offset)
        elif offSize == 3:
            result += struct.pack('>I', offset)[1:]  # 3 bytes
        else:
            result += struct.pack('>I', offset)
        offset += len(d)
    # Last offset
    if offSize == 1:
        result += struct.pack('B', offset)
    elif offSize == 2:
        result += struct.pack('>H', offset)
    elif offSize == 3:
        result += struct.pack('>I', offset)[1:]
    else:
        result += struct.pack('>I', offset)

    # Write data
    for d in data_list:
        result += d

    return result

print("Helper functions defined")

